-- =============================================================================
-- 06_seed_assessment_db.sql : ASSESSMENT SERVICE SEED DATA (assessment_db)
-- Khớp 100% V1__init_assessment.sql (JSONB options/correct_answer/answers)
-- 8 Types, 18 Assessments, 180 Questions (720 options), 64 Attempts (640 candidate answers)
-- =============================================================================
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS assessment_types (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    duration_minutes INT,
    max_score SMALLINT DEFAULT 100,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS assessments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    type_id UUID NOT NULL REFERENCES assessment_types(id),
    title VARCHAR(255) NOT NULL,
    description TEXT,
    instructions TEXT,
    passing_score SMALLINT DEFAULT 70,
    time_limit_minutes INT,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_by UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS assessment_questions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    assessment_id UUID NOT NULL REFERENCES assessments(id) ON DELETE CASCADE,
    question_text TEXT NOT NULL,
    question_type VARCHAR(30) NOT NULL CHECK (question_type IN ('SINGLE_CHOICE', 'MULTIPLE_CHOICE', 'TRUE_FALSE', 'SHORT_ANSWER', 'CODE')),
    options JSONB,
    correct_answer JSONB,
    explanation TEXT,
    points SMALLINT DEFAULT 1,
    order_index INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS assessment_attempts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    assessment_id UUID NOT NULL REFERENCES assessments(id),
    user_id UUID NOT NULL,
    started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at TIMESTAMPTZ,
    score SMALLINT,
    max_score SMALLINT,
    percentage DECIMAL(5,2),
    status VARCHAR(20) NOT NULL DEFAULT 'IN_PROGRESS' CHECK (status IN ('IN_PROGRESS', 'SUBMITTED', 'GRADED', 'EXPIRED')),
    answers JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 1. 8 Assessment Types
ON CONFLICT (code) DO NOTHING;

-- 2. 18 Assessments
ON CONFLICT (id) DO NOTHING;

-- 3. 180 Assessment Questions (720 JSONB Answer Options)
ON CONFLICT (id) DO NOTHING;

-- 4. 64 Assessment Attempts (640 Candidate Answers in JSONB)
ON CONFLICT (id) DO NOTHING;
